CREATE FUNCTION public.design_catalog_move(_id uuid,_direction integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,private AS $$ DECLARE c design_catalogs; n design_catalogs; BEGIN IF NOT private.is_active(auth.uid()) OR NOT (private.is_admin(auth.uid()) OR private.has_permission(auth.uid(),'settings.role')) THEN RAISE EXCEPTION 'Không có quyền Cài đặt' USING ERRCODE='42501'; END IF; IF _direction NOT IN (-1,1) THEN RAISE EXCEPTION 'Hướng sắp xếp không hợp lệ'; END IF; PERFORM pg_advisory_xact_lock(hashtext('design_catalog_order')); SELECT * INTO c FROM design_catalogs WHERE id=_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Danh mục không tồn tại'; END IF; WITH ranks AS(SELECT id,row_number() OVER(ORDER BY position,name,id)::integer AS p FROM design_catalogs WHERE workflow_kind=c.workflow_kind AND kind=c.kind) UPDATE design_catalogs d SET position=r.p FROM ranks r WHERE d.id=r.id; SELECT * INTO c FROM design_catalogs WHERE id=_id; SELECT * INTO n FROM design_catalogs WHERE workflow_kind=c.workflow_kind AND kind=c.kind AND position=c.position+_direction FOR UPDATE; IF FOUND THEN UPDATE design_catalogs SET position=CASE WHEN id=c.id THEN n.position ELSE c.position END WHERE id IN(c.id,n.id); END IF; END $$;
REVOKE ALL ON FUNCTION public.design_catalog_move(uuid,integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.design_catalog_move(uuid,integer) TO authenticated;